from openpyxl import load_workbook
path='/root/output/result.xlsx'
wb=load_workbook(path, data_only=False)
ws=wb['Task']
print('Sheet names:', wb.sheetnames)
for coord in ['H12','L17','H19','L24','H26','L31','H35','L40','H42','H43','H44','H45','H46','H47','H50','L50']:
    print(coord, ws[coord].value)
# Extra checks: no _xlfn, no Python artifacts, no added sheets
bad=[]
for wsx in wb.worksheets:
    for row in wsx.iter_rows():
        for cell in row:
            v=cell.value
            if isinstance(v,str) and v.startswith('='):
                if '_xlfn' in v or '{' in v or '}' in v or "f'" in v or 'None' in v:
                    bad.append((wsx.title, cell.coordinate, v))
print('bad_formula_artifacts:', bad)
print('sheet_count:', len(wb.sheetnames))
